<script setup>
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import request from '../api/request'
const router = useRouter(); const products = ref([]); const loading = ref(false); const message = ref(''); const messageType = ref(''); const showForm = ref(false); const editingId = ref(null)
const categories = [{ id: 1, name: '数码办公' }, { id: 2, name: '家居生活' }, { id: 3, name: '服饰出行' }, { id: 4, name: '运动健康' }, { id: 5, name: '美妆个护' }]
const form = ref({ name: '', price: '', stock: '', description: '', imageUrl: '', categoryId: 1 })
const fallbackImage = 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=900&q=80'
async function loadProducts() { loading.value = true; try { const response = await request.get('/products'); if (response.data.code === 200) products.value = response.data.data || []; else showMessage(response.data.message || '获取商品失败', 'error') } catch (error) { showMessage(error.response?.data?.message || '获取商品失败，请检查后端', 'error') } finally { loading.value = false } }
function showMessage(text, type = 'success') { message.value = text; messageType.value = type }
function blankForm() { return { name: '', price: '', stock: '', description: '', imageUrl: '', categoryId: 1 } }
function openCreateForm() { editingId.value = null; form.value = blankForm(); showForm.value = true }
function openEditForm(product) { editingId.value = product.id; form.value = { name: product.name, price: product.price, stock: product.stock, description: product.description || '', imageUrl: product.imageUrl || '', categoryId: product.categoryId || 1 }; showForm.value = true }
async function saveProduct() { if (!form.value.name.trim() || Number(form.value.price) <= 0 || Number(form.value.stock) < 0) return showMessage('请正确填写名称、价格和库存', 'error'); const data = { name: form.value.name.trim(), price: Number(form.value.price), stock: Number(form.value.stock), description: form.value.description.trim(), imageUrl: form.value.imageUrl.trim(), categoryId: Number(form.value.categoryId) }; try { const response = editingId.value === null ? await request.post('/products', data) : await request.put(`/products/${editingId.value}`, data); if (response.data.code === 200) { showMessage(editingId.value === null ? '商品新增成功' : '商品修改成功'); showForm.value = false; await loadProducts() } else showMessage(response.data.message || '保存商品失败', 'error') } catch (error) { showMessage(error.response?.data?.message || '保存商品失败，请检查管理员权限', 'error') } }
async function deleteProduct(id) { if (!window.confirm('确定要删除这个商品吗？')) return; try { const response = await request.delete(`/products/${id}`); if (response.data.code === 200) { showMessage('商品删除成功'); await loadProducts() } else showMessage(response.data.message || '删除商品失败', 'error') } catch (error) { showMessage(error.response?.data?.message || '删除商品失败', 'error') } }
onMounted(loadProducts)
</script>

<template>
  <main class="admin-product-page"><header class="admin-page-header"><div><div class="section-kicker">ADMIN CONSOLE</div><h1>商品管理</h1><p>维护商品名称、图片、分类、价格和库存</p></div><button class="primary-button" type="button" @click="openCreateForm">新增商品</button></header><p v-if="message" class="notice" :class="messageType">{{ message }}</p><p v-if="loading" class="loading-message">商品加载中...</p>
    <section v-else class="admin-product-table-wrapper"><table class="admin-product-table"><thead><tr><th>图片</th><th>ID</th><th>商品名称</th><th>分类</th><th>价格</th><th>库存</th><th>操作</th></tr></thead><tbody><tr v-for="product in products" :key="product.id"><td><img class="admin-product-thumb" :src="product.imageUrl || fallbackImage" :alt="product.name" @error="$event.target.src = fallbackImage" /></td><td>{{ product.id }}</td><td>{{ product.name }}</td><td>{{ categories.find(item => item.id === product.categoryId)?.name || '未分类' }}</td><td>￥{{ Number(product.price).toFixed(2) }}</td><td>{{ product.stock }}</td><td class="admin-actions"><button type="button" @click="openEditForm(product)">编辑</button><button class="danger-text-button" type="button" @click="deleteProduct(product.id)">删除</button></td></tr></tbody></table></section>
    <section v-if="showForm" class="product-form-card"><h2>{{ editingId === null ? '新增商品' : '编辑商品' }}</h2><form @submit.prevent="saveProduct"><label>商品名称<input v-model="form.name" type="text" maxlength="100" required /></label><label>商品分类<select v-model="form.categoryId"><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>商品价格<input v-model="form.price" type="number" min="0.01" step="0.01" required /></label><label>商品库存<input v-model="form.stock" type="number" min="0" required /></label><label class="full-field">商品图片 URL<input v-model="form.imageUrl" type="url" placeholder="https://...jpg" /><img v-if="form.imageUrl" class="form-image-preview" :src="form.imageUrl" alt="图片预览" @error="$event.target.style.display = 'none'" /></label><label class="full-field">商品描述<textarea v-model="form.description" maxlength="500"></textarea></label><div class="form-actions"><button class="primary-button" type="submit">保存</button><button class="secondary-button" type="button" @click="showForm = false">取消</button></div></form></section><button class="back-admin-button" type="button" @click="router.push('/products')">返回商品列表</button>
  </main>
</template>
